contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address callee, bytes memory data) public payable {
        // The low-level call will succeed iff callee is this contract and data is empty,
        // because this contract has no fallback/receive to reject empty calls.
        // Actually, forwarding to this contract with empty data succeeds.
        // To make a general rule that holds: forward reverts iff the external call fails,
        // but we cannot observe the external call's success directly from outside.
        // However, we know that calling this test contract with empty calldata succeeds
        // because this contract has a receive function, so forward(callee, data) will not revert
        // when callee == address(this) and data.length == 0.
        bool reverted = false;
        if (callee == address(this) && data.length == 0) {
            try c.forward(callee, data) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted == false);
        } else {
            // For other inputs, we cannot make a general claim about revert,
            // so we must exclude them with a require.
            require(false, "excluded input");
        }
    }

    receive() external payable {}
}

